{
  "summary": "The design fails to meet the required 72‑hour idempotency window and can lose signing capability after secret rotation, violating core reliability goals. Minor clarity gaps remain around undefined terminology.",
  "findings": [
    {
      "severity": "blocker",
      "category": "reliability",
      "passage_id": "a8797a66ec8d-d6",
      "requirement_ids": ["a8797a66ec8d-r2"],
      "issue": "Receipts expire 24 hours, but the specification requires Idempotency‑Key retries to be honored for 72 hours. After receipt cleanup the API treats a retry as a new submission, breaking the idempotency guarantee.",
      "recommendation": "Extend receipt retention to at least 72 hours (or keep a lightweight idempotency record beyond receipt expiry) and ensure retries within that window are still matched to the original response.",
      "counterexample": {
        "scenario": "Client submits an event at T=0 and receives a receipt. At T=30 h the client retries the identical payload with the same Idempotency‑Key. The receipt was removed at T=24 h, so the API treats the request as new and creates a second event.",
        "violation": "Violates requirement a8797a66ec8d-r2 (honor the documented 72‑hour submission retry window)."
      }
    },
    {
      "severity": "blocker",
      "category": "reliability",
      "passage_id": "a8797a66ec8d-d8",
      "requirement_ids": ["a8797a66ec8d-r3"],
      "issue": "Secret bytes are erased 30 minutes after rotation. Delivery retries may be scheduled up to 24 hours after enqueue; if the secret for the event’s key_version has been erased, signing fails, contradicting the requirement that rotation must not prevent eligible retries from being signed.",
      "recommendation": "Retain secret bytes for at least the maximum delivery‑retry window (24 h) plus a safety margin, or cache the secret needed for pending retries before erasure.",
      "counterexample": {
        "scenario": "An event is enqueued at T=0 with key_version 1. Rotation occurs at T=5 min, erasing the secret for version 1 at T=30 min. A delivery retry is attempted at T=2 h; the signing process cannot load the required secret and the job is marked signing_failed.",
        "violation": "Violates requirement a8797a66ec8d-r3 (secret rotation must not prevent an otherwise eligible retry from being signed)."
      }
    },
    {
      "severity": "nit",
      "category": "clarity",
      "passage_id": "a8797a66ec8d-d6",
      "requirement_ids": [],
      "issue": "The term “receipt” is used without an explicit definition; readers must infer its structure and lifecycle from context.",
      "recommendation": "Add a brief definition of a receipt (e.g., “a record storing the payload digest, original response, and expiration timestamp for a given tenant_id and Idempotency‑Key”).",
      "counterexample": {
        "scenario": "A new engineer reads the design and cannot determine whether a receipt includes the response body, headers, or only metadata, leading to implementation ambiguity.",
        "violation": "Reduces clarity but does not directly breach a stated requirement."
      }
    },
    {
      "severity": "nit",
      "category": "clarity",
      "passage_id": "a8797a66ec8d-d9",
      "requirement_ids": [],
      "issue": "Reference to “Polling status” is made without describing the polling API or its output, leaving its security implications unclear.",
      "recommendation": "Provide a short description of the polling endpoint and confirm that it returns no secret material.",
      "counterexample": {
        "scenario": "A security reviewer cannot verify that polling does not inadvertently leak secret identifiers.",
        "violation": "Potentially obscures security posture but not a direct requirement breach."
      }
    }
  ]
}

{
  "summary": "The design uses a single PostgreSQL transaction that atomically updates stock and reservation state, enforces idempotency via a tenant‑scoped key, and restores stock exactly once on cancellation. Under READ COMMITTED isolation the UPDATE … WHERE available>=quantity guard prevents negative stock, and the state‑check on cancellation prevents double restores. The described failure handling (rollback on pre‑commit crash, replay on post‑commit loss, 503 on deadlock/outage) satisfies the stated requirements. No concrete violation of the explicit goals, risks, or acceptance tests is identified.",
  "findings": []
}

{
  "summary": "The specification fails the mandatory Alternatives rule by listing alternative designs without any documented evaluation or rejection rationale.",
  "findings": [
    {
      "severity": "major",
      "category": "clarity",
